js = "/* Generated by scripts/make-ext.py: MFOB (base station), Jarvis, Wrist module, Aurelia, Bench school. */\n(function () {\n"
js += "BRANCHES.push(...%s);\n" % json.dumps(branches, ensure_ascii=False)
js += "PHASES.push(...%s);\n" % json.dumps(phases, ensure_ascii=False)
js += "PHASES.unshift(...%s);\n" % json.dumps(front_phases, ensure_ascii=False)
js += "NODES.push(...%s);\n" % json.dumps(nodes, ensure_ascii=False, indent=0)
js += "PARTS.push(...%s);\n" % json.dumps(parts, ensure_ascii=False)
js += "%s.forEach(([id, t, d, from]) => TERMS.push({ id, t, d, from }));\n" % json.dumps(terms, ensure_ascii=False)
js += "COMMANDS.push(...%s);\n" % json.dumps(commands, ensure_ascii=False)
js += "SAFETY.push(...%s);\n" % json.dumps(safety, ensure_ascii=False)
js += """// R2 needs audio out: the Pi 5 has no headphone jack
const r2 = NODES.find(n => n.id === 'R2');
if (r2) { r2.needs = (r2.needs || []).concat('usbaudio'); r2.learn.push('The Pi 5 has no headphone jack. To hear it, plug your headset into the USB sound card, or pair your Bluetooth earbuds, then right-click the speaker icon on the taskbar to pick the output.'); }
})();
"""
pathlib.Path(__file__).resolve().parent.parent.joinpath('www', 'content-ext.js').write_text(js)
print('wrote content-ext.js:', len(nodes), 'nodes,', len(parts), 'parts,', len(terms), 'terms')
